void OffloadAudioRenderSink::CheckFlushThread()
{
    if (flushThread_ != nullptr && flushThread_->joinable()) {
        AUDIO_INFO_LOG("OffloadFlushProbe[CheckFlushThread] joining");
        flushThread_->join();
        AUDIO_INFO_LOG("OffloadFlushProbe[CheckFlushThread] joined");
    }
    flushThread_.reset();
}
